import{geography}from'./map-geography.js';
import{facilities,nodes,lookup,isActive,laneGroups,openExceptions}from'./data.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
let camera={zoom:1,dx:0,dy:0,extent:'network'};
export const resetMapCamera=()=>{camera={zoom:1,dx:0,dy:0,extent:'network'}};
export const zoomMap=amount=>{camera.zoom=Math.min(3,Math.max(.75,camera.zoom*amount))};
export const setMapExtent=extent=>{camera={zoom:1,dx:0,dy:0,extent}};
export const panMap=(dx,dy)=>{camera.dx=Math.min(700,Math.max(-700,camera.dx+dx));camera.dy=Math.min(450,Math.max(-450,camera.dy+dy))};
const operatingStates=new Set(['Georgia','Texas','Minnesota','Colorado','Ohio','Louisiana','California','Illinois']);
const initialOffsets={GNV:[28,-58],DOR:[28,14],HSP:[20,21],HOU:[-158,13],BTR:[25,-22],LOR:[-62,-60],MRK:[-148,-24],SID:[25,-39],DEN:[10,-60],RED:[-45,23],YYC:[23,-15],STL:[-110,16],CLT:[15,18],DAY:[15,15]};
function transform(){const k=(camera.extent==='country'?.77:.84)*camera.zoom,cx=camera.extent==='country'?490:395,cy=camera.extent==='country'?255:247;return{k,tx:450-cx*k+camera.dx,ty:280-cy*k+camera.dy}}
function project(id,t){const p=geography.points[id];return[p[0]*t.k+t.tx,p[1]*t.k+t.ty]}
const button=(text,action,id='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" data-id="${id}">${text}</button>`;
const typeShort=f=>f.id==='GNV'?'HEADQUARTERS':f.id==='DOR'?'POWER & GAS':['HSP','SID'].includes(f.id)?'SERVICE PARTNERS':f.id==='YYC'?'CANADA · CITY PIN':f.id==='MRK'?'MAILING · CITY PIN':'PUBLISHED OFFICE';
export function renderFreightNetwork({shipments,data,filters,mode,list,weight,finance,icon}){
const selected=shipments.filter(s=>s.status!=='Cancelled'&&(mode!=='active'||isActive(s))),lanes=laneGroups(selected),max=Math.max(1,...lanes.map(l=>weight==='spend'?l.spend:l.ships.length));
const subtitle=mode==='locations'?`${facilities.length} published locations · United States & Canada`:`${selected.length} demo shipments · ${lanes.length} directional lanes`;
const toolbar=`<div class="card-head map-panel-head"><div><h2>Mansfield’s location network</h2><p>${subtitle}</p></div><div class="segmented" aria-label="Map mode">${[['locations','Locations'],['active','Active freight'],['history','Historical flow']].map(([id,label])=>button(label,'map-mode',id,mode===id?'active':'')).join('')}</div></div>`;
if(list){const rows=mode==='locations'?facilities.map(f=>`<tr><td><button type="button" class="link" data-action="facility" data-id="${f.id}">${f.name}, ${f.state}</button><small>${f.type}</small></td><td style="white-space:normal">${f.address}</td><td style="white-space:normal">${f.quality}</td></tr>`).join(''):lanes.map(l=>`<tr><td><button type="button" class="link" data-action="lane" data-id="${l.key}">${lookup(l.origin).name} → ${lookup(l.destination).name}</button></td><td>${l.ships.length} loads</td><td>${openExceptions(data,l.ships).length} open issues${finance?' · '+money(l.spend):''}</td></tr>`).join('');return`<section class="card network-card">${toolbar}<div class="map-directory table-wrap"><table><thead><tr><th>${mode==='locations'?'Published location':'Directional lane'}</th><th>${mode==='locations'?'Directory address':'Demo shipments'}</th><th>${mode==='locations'?'Pin / source status':'Open issues'}</th></tr></thead><tbody>${rows}</tbody></table></div><div class="map-bottom">${button(icon('map')+' Map view','map-list','','btn sm')}<button class="link" data-action="location-sources">Location sources & notes</button></div></section>`}
const t=transform();const showNodes=mode==='locations'?facilities:nodes;const plotted=showNodes.map(n=>({...n,p:project(n.id,t)}));
const labelBoxes=[];const labels=plotted.map(n=>{const[x,y]=n.p;if(x<-30||x>930||y<-30||y>590)return'';const f=facilities.find(f=>f.id===n.id),isApprox=f&&['SID','MRK','YYC'].includes(f.id),isSelected=filters.facility===n.id,countIn=selected.filter(s=>s.destination===n.id).length,countOut=selected.filter(s=>s.origin===n.id).length;
const w=f?143:115,h=f?45:36,off=initialOffsets[n.id]||[15,-25];let bx=x+off[0],by=y+off[1];const candidates=[[bx,by],[x+20,y-h-10],[x-w-20,y-h-12],[x-w/2,y+25],[x+20,y+45],[x-w-20,y+40],[x-w/2,y-100],[x+30,y+95]];
const overlap=(bx,by)=>labelBoxes.some(b=>bx<b.x+b.w+5&&bx+w+5>b.x&&by<b.y+b.h+5&&by+h+5>b.y);
for(let[cx,cy]of candidates){cx=Math.min(895-w,Math.max(5,cx));cy=Math.min(550-h,Math.max(12,cy));if(!overlap(cx,cy)){bx=cx;by=cy;break}}
bx=Math.min(895-w,Math.max(5,bx));by=Math.min(550-h,Math.max(12,by));labelBoxes.push({x:bx,y:by,w,h});
const ax=Math.max(bx+8,Math.min(bx+w-8,x)),ay=Math.max(by+6,Math.min(by+h-6,y));const subtitle=mode==='locations'?(f?typeShort(f):'DEMO EXTERNAL LOCATION'):`${countIn} inbound · ${countOut} outbound`;
const title=f?`${f.name}, ${f.state}\n${f.address}\n${f.quality}\n${f.sourceNote}`:`${n.name} · synthetic external location`;
return`<g class="geo-location ${isSelected?'selected':''} ${isApprox?'approx':''}" ${f?`data-action="map-facility" data-id="${n.id}" role="button" tabindex="0" aria-label="Filter ${esc(n.name)}, ${n.state}. ${countIn} inbound and ${countOut} outbound demo shipments."`:''}><title>${esc(title)}</title><path d="M${x} ${y}L${ax} ${ay}" class="label-leader"/><circle class="pin-halo" cx="${x}" cy="${y}" r="${f?.id==='GNV'?15:11}"/><circle class="pin-core" cx="${x}" cy="${y}" r="${f?.id==='GNV'?6:5}"/><g class="location-label" transform="translate(${bx},${by})"><rect width="${w}" height="${h}" rx="5"/><rect class="label-accent" width="3" height="${h-14}" x="0" y="7" rx="1.5"/><text class="city-label" x="11" y="18">${esc(n.name.replace(' customer','').replace(' supplier',''))}</text><text class="location-sub" x="11" y="34">${subtitle}</text>${isApprox?'<circle cx="132" cy="12" r="3" fill="#a86300"/>':''}</g></g>`}).join('');
const lines=mode==='locations'?'':lanes.map(l=>{const[a,b]=[project(l.origin,t),project(l.destination,t)],problem=openExceptions(data,l.ships).length>0;const dx=b[0]-a[0],dy=b[1]-a[1],dist=Math.hypot(dx,dy)||1;const mx=(a[0]+b[0])/2+dy/dist*28,my=(a[1]+b[1])/2-dx/dist*28;const d=`M${a[0]},${a[1]} Q${mx},${my} ${b[0]},${b[1]}`,width=mode==='history'?1.8+(weight==='spend'?l.spend:l.ships.length)/max*4:2.2;return`<g class="geo-lane ${problem?'issue':''}" data-action="lane" data-id="${l.key}" role="button" tabindex="0" aria-label="${lookup(l.origin).name} to ${lookup(l.destination).name}, ${l.ships.length} shipments"><title>${lookup(l.origin).name} → ${lookup(l.destination).name}\n${l.ships.length} synthetic loads${finance?' · '+money(l.spend):''}${problem?' · Open exceptions':''}</title><path class="lane-hit" d="${d}"/><path class="lane-visible" d="${d}" style="stroke-width:${width}" marker-end="url(#${problem?'lane-amber':'lane-navy'})"/></g>`}).join('');
const statePaths=geography.states.map(s=>`<path class="state ${operatingStates.has(s.name)?'operating':''}" d="${s.d}"/>`).join('');
const stateLabels=geography.labels.map(l=>{const x=l.xy[0]*t.k+t.tx,y=l.xy[1]*t.k+t.ty;return`<text class="state-label" x="${x}" y="${y}">${l.name}</text>`}).join('');
return`<section class="card network-card">${toolbar}<div class="geo-map" id="freight-map"><div class="map-floating-title"><span class="map-live-dot"></span>${mode==='locations'?'PUBLIC LOCATION DIRECTORY':'SYNTHETIC FREIGHT FLOWS'}</div><svg class="geo-svg" viewBox="0 0 900 560" aria-label="Mansfield Energy published US and Canada locations; select a label to filter. An accessible list is available." role="group"><defs><marker id="lane-navy" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 10 5 0 10z" fill="#315879"/></marker><marker id="lane-amber" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 10 5 0 10z" fill="#ba7a2b"/></marker><pattern id="map-grid" width="70" height="70" patternUnits="userSpaceOnUse"><path d="M70 0H0V70" fill="none" stroke="#dce5eb" stroke-width=".5"/></pattern></defs><rect width="900" height="560" fill="#edf3f6"/><rect width="900" height="560" fill="url(#map-grid)"/><g transform="translate(${t.tx},${t.ty}) scale(${t.k})">${geography.background.map(c=>`<path class="neighbor-country" d="${c.d}"/>`).join('')}${statePaths}</g>${stateLabels}<text class="country-label" x="700" y="65">CANADA</text><text class="country-label" x="210" y="250">UNITED STATES</text>${lines}${labels}${mode!=='locations'?`<g class="terminal-node"><rect x="${project('DAY',t)[0]-3}" y="${project('DAY',t)[1]-3}" width="6" height="6" fill="#89959d"/><title>Dayton · synthetic carrier terminal reference; not live GPS.</title></g>`:''}</svg><div class="geo-controls"><button data-action="map-zoom-in" aria-label="Zoom in" title="Zoom in">+</button><button data-action="map-zoom-out" aria-label="Zoom out" title="Zoom out">−</button><button data-action="map-fit" data-id="network" aria-label="Fit Mansfield network" title="Fit network">${icon('refresh')}</button></div><div class="geo-bottom-controls"><div class="geo-view-switch">${button('Fit network','map-fit','network',camera.extent==='network'?'active':'')}${button('North America','map-fit','country',camera.extent==='country'?'active':'')}</div>${mode==='history'&&finance?`<select aria-label="Historical lane sizing" id="map-weight"><option value="volume" ${weight==='volume'?'selected':''}>Size by volume</option><option value="spend" ${weight==='spend'?'selected':''}>Size by spend</option></select>`:''}${button(icon('list')+' List view','map-list','','btn sm')}</div></div><div class="map-bottom"><div class="geo-legend"><span><i class="geo-key"></i>Published location</span><span><i class="geo-key approximate"></i>City / mailing pin</span>${mode!=='locations'?'<span><i class="geo-key issue"></i>Service issue</span>':''}</div><button class="link" data-action="location-sources">Source & location notes ${icon('info')}</button></div><div class="map-disclosure">${mode==='locations'?'11 detailed entries from Mansfield’s public directory. Offices and mailing entries are not verified receiving docks.':'Demo connections are network flows, not driven routes or actual Mansfield shipment activity.'} <span>Drag to pan · Use + / − to zoom</span></div>${filters.facility!=='all'?`<div class="selected-map-location"><div><strong>${lookup(filters.facility).name}</strong><small>${facilities.find(f=>f.id===filters.facility)?.address||''}</small></div>${button('Open workspace →','facility',filters.facility,'btn primary sm')}</div>`:''}</section>`}
